-- Function definitions for Phase 8-10. Production was applied through Supabase migration execution.
create or replace function public.apply_community_reputation_event(p_user_id uuid,p_event_type text,p_points integer,p_source_id uuid default null,p_metadata jsonb default '{}'::jsonb) returns boolean language plpgsql security definer set search_path=public as $$ declare inserted boolean:=false; begin if p_user_id is null or p_event_type is null or length(trim(p_event_type))>64 then raise exception 'invalid_reputation_event'; end if; insert into public.community_reputation_events(user_id,event_type,points,source_id,metadata) values(p_user_id,trim(p_event_type),p_points,p_source_id,coalesce(p_metadata,'{}'::jsonb)) on conflict do nothing; if found then inserted:=true; insert into public.community_reputation(user_id) values(p_user_id) on conflict do nothing; update public.community_reputation set trust_score=greatest(0,least(100,trust_score+p_points)),moderation_strikes=moderation_strikes+case when p_event_type='moderation_strike' then 1 else 0 end,community_posts=community_posts+case when p_event_type='community_post' then 1 else 0 end,helpful_reactions=helpful_reactions+case when p_event_type='helpful_reaction' then 1 else 0 end,last_activity_at=now(),updated_at=now() where user_id=p_user_id; end if; return inserted; end; $$;
revoke all on function public.apply_community_reputation_event(uuid,text,integer,uuid,jsonb) from public,anon,authenticated;
create or replace function public.sync_community_post_reputation() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.author_id is not null then perform public.apply_community_reputation_event(new.author_id,'community_post',1,new.id,jsonb_build_object('author_type',new.author_type)); end if; return new; end; $$;
drop trigger if exists trg_sync_community_post_reputation on public.predictions_comments; create trigger trg_sync_community_post_reputation after insert on public.predictions_comments for each row execute function public.sync_community_post_reputation(); revoke all on function public.sync_community_post_reputation() from public,anon,authenticated;
create or replace function public.claim_daily_checkin() returns table(current_streak integer,best_streak integer,already_claimed boolean) language plpgsql security definer set search_path=public as $$ declare v_user uuid:=auth.uid(); v public.user_streaks; d date:=current_date; begin if v_user is null then raise exception 'authentication_required' using errcode='42501'; end if; select * into v from public.user_streaks where user_id=v_user for update; if not found then insert into public.user_streaks(user_id,current_streak,best_streak,last_checkin_date) values(v_user,1,1,d) returning * into v; return query select v.current_streak,v.best_streak,false; return; end if; if v.last_checkin_date=d then return query select v.current_streak,v.best_streak,true; return; end if; v.current_streak:=case when v.last_checkin_date=d-1 then v.current_streak+1 else 1 end; v.best_streak:=greatest(v.best_streak,v.current_streak); update public.user_streaks set current_streak=v.current_streak,best_streak=v.best_streak,last_checkin_date=d,updated_at=now() where user_id=v_user; insert into public.xp_transactions(user_id,amount,reason,source_type,source_id,metadata) values(v_user,10,'Daily community check-in','daily_checkin',gen_random_uuid(),jsonb_build_object('date',d)); return query select v.current_streak,v.best_streak,false; end; $$; revoke all on function public.claim_daily_checkin() from public,anon; grant execute on function public.claim_daily_checkin() to authenticated;
create or replace function public.get_my_growth_link() returns table(code text,url text) language sql stable security definer set search_path=public as $$ select rc.code,'https://iwannaberich.xyz/account.html?ref='||rc.code from public.referral_codes rc where rc.user_id=auth.uid() and rc.active=true order by rc.created_at asc limit 1; $$; revoke all on function public.get_my_growth_link() from public,anon; grant execute on function public.get_my_growth_link() to authenticated;
